-- Read-only: builds the live database's structure (no data) as one SQL script, for the staging copy.
with
tbl as (select c.oid, c.relname, c.relrowsecurity, c.relforcerowsecurity, c.relacl from pg_class c join pg_namespace n on n.oid = c.relnamespace
         where n.nspname = 'public' and c.relkind in ('r', 'p')
           and not exists (select 1 from pg_depend d where d.objid = c.oid and d.deptype = 'e')),
s_ext as (select string_agg(format('create extension if not exists %I with schema %I;', e.extname, n.nspname), E'\n' order by e.extname) s
           from pg_extension e join pg_namespace n on n.oid = e.extnamespace where e.extname <> 'plpgsql'),
s_enum as (select string_agg(format('do $e$ begin create type public.%I as enum (%s); exception when duplicate_object then null; end $e$;', t.typname,
             (select string_agg(quote_literal(enumlabel), ', ' order by enumsortorder) from pg_enum where enumtypid = t.oid)), E'\n') s
           from pg_type t join pg_namespace n on n.oid = t.typnamespace where n.nspname = 'public' and t.typtype = 'e'),
s_seq as (select string_agg(format('create sequence if not exists public.%I;', c.relname), E'\n' order by c.relname) s
           from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relkind = 'S'
            and not exists (select 1 from pg_depend d where d.objid = c.oid and d.deptype = 'i')),
s_tab as (select string_agg(format('create table if not exists public.%I (%s);', t.relname,
             (select string_agg(format('%I %s%s%s', a.attname, format_type(a.atttypid, a.atttypmod),
                 case a.attidentity when 'a' then ' generated always as identity' when 'd' then ' generated by default as identity' else '' end,
                 case when a.attgenerated = 's' then ' generated always as (' || pg_get_expr(ad.adbin, ad.adrelid) || ') stored' else '' end), ', ' order by a.attnum)
                from pg_attribute a left join pg_attrdef ad on ad.adrelid = a.attrelid and ad.adnum = a.attnum
               where a.attrelid = t.oid and a.attnum > 0 and not a.attisdropped)), E'\n' order by t.relname) s from tbl t),
s_fun as (select string_agg(pg_get_functiondef(p.oid) || ';', E'\n' order by p.proname, pg_get_function_identity_arguments(p.oid)) s
           from pg_proc p join pg_namespace n on n.oid = p.pronamespace
          where n.nspname = 'public' and p.prokind in ('f', 'p')
            and not exists (select 1 from pg_depend d where d.objid = p.oid and d.deptype = 'e')),
s_def as (select string_agg(format('alter table public.%I alter column %I set default %s;', t.relname, a.attname, pg_get_expr(ad.adbin, ad.adrelid)), E'\n' order by t.relname, a.attnum) s
           from tbl t join pg_attribute a on a.attrelid = t.oid join pg_attrdef ad on ad.adrelid = a.attrelid and ad.adnum = a.attnum
          where a.attidentity = '' and a.attgenerated = '' and not a.attisdropped),
s_nn as (select string_agg(format('alter table public.%I alter column %I set not null;', t.relname, a.attname), E'\n' order by t.relname, a.attnum) s
           from tbl t join pg_attribute a on a.attrelid = t.oid where a.attnum > 0 and a.attnotnull and not a.attisdropped and a.attidentity = ''),
s_con as (select string_agg(format('alter table public.%I add constraint %I %s;', t.relname, co.conname, pg_get_constraintdef(co.oid)), E'\n'
             order by case co.contype when 'p' then 1 when 'u' then 2 when 'x' then 3 when 'c' then 4 else 5 end, t.relname, co.conname) s
           from pg_constraint co join tbl t on t.oid = co.conrelid where co.contype in ('p', 'u', 'c', 'f', 'x')),
s_idx as (select string_agg(pg_get_indexdef(i.indexrelid) || ';', E'\n' order by t.relname, i.indexrelid::regclass::text) s from pg_index i join tbl t on t.oid = i.indrelid
          where not exists (select 1 from pg_constraint co where co.conindid = i.indexrelid)),
s_view as (select string_agg(format('create or replace view public.%I as %s', c.relname, pg_get_viewdef(c.oid)), E'\n' order by c.oid) s
           from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relkind = 'v'),
s_trg as (select string_agg(pg_get_triggerdef(tg.oid) || ';', E'\n' order by c.relname, tg.tgname) s
           from pg_trigger tg join pg_class c on c.oid = tg.tgrelid join pg_namespace n on n.oid = c.relnamespace
          where not tg.tgisinternal and (n.nspname = 'public' or (n.nspname = 'auth' and exists (
            select 1 from pg_proc p join pg_namespace pn on pn.oid = p.pronamespace where p.oid = tg.tgfoid and pn.nspname = 'public')))),
s_rls as (select string_agg(format('alter table public.%I enable row level security;', relname) ||
            case when relforcerowsecurity then format(' alter table public.%I force row level security;', relname) else '' end, E'\n' order by relname) s
           from tbl where relrowsecurity),
s_pol as (select string_agg(format('drop policy if exists %I on %I.%I; create policy %I on %I.%I as %s for %s to %s%s%s;',
             policyname, schemaname, tablename, policyname, schemaname, tablename, permissive, cmd,
             (select string_agg(quote_ident(r), ', ') from unnest(roles) r),
             coalesce(' using (' || qual || ')', ''), coalesce(' with check (' || with_check || ')', '')), E'\n' order by schemaname, tablename, policyname) s
           from pg_policies where schemaname in ('public', 'storage')),
s_tgrant as (select string_agg(format('revoke all on table public.%I from anon, authenticated;', t.relname) ||
             coalesce((select ' ' || string_agg(format('grant %s on table public.%I to %I;', x.privilege_type, t.relname, r.rolname), ' ')
                from aclexplode(t.relacl) x join pg_roles r on r.oid = x.grantee where r.rolname in ('anon', 'authenticated', 'service_role')), ''), E'\n' order by t.relname) s
           from tbl t where t.relacl is not null),
s_fgrant as (select string_agg(format('revoke all on function public.%I(%s) from public, anon, authenticated;', p.proname, pg_get_function_identity_arguments(p.oid)) ||
             coalesce((select ' ' || string_agg(format('grant execute on function public.%I(%s) to %s;', p.proname, pg_get_function_identity_arguments(p.oid),
                case when x.grantee = 0 then 'public' else quote_ident(r.rolname) end), ' ')
                from aclexplode(p.proacl) x left join pg_roles r on r.oid = x.grantee where x.grantee = 0 or r.rolname in ('anon', 'authenticated', 'service_role')), ''), E'\n' order by p.proname, pg_get_function_identity_arguments(p.oid)) s
           from pg_proc p join pg_namespace n on n.oid = p.pronamespace
          where n.nspname = 'public' and p.prokind in ('f', 'p') and p.proacl is not null
            and not exists (select 1 from pg_depend d where d.objid = p.oid and d.deptype = 'e')),
s_bkt as (select string_agg(format('insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values (%L, %L, %L, %s, %s) on conflict (id) do nothing;',
             id, name, public, coalesce(file_size_limit::text, 'null'), coalesce(quote_literal(allowed_mime_types::text) || '::text[]', 'null')), E'\n' order by id) s from storage.buckets),
s_pub as (select string_agg(format('alter publication supabase_realtime add table public.%I;', tablename), E'\n' order by tablename) s
           from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public')
select '-- STAGING SCHEMA FROM LIVE ' || now()::text || E'\nset check_function_bodies = off;\n' ||
  concat_ws(E'\n',
    '-- extensions', (select s from s_ext), '-- types', (select s from s_enum), '-- sequences', (select s from s_seq),
    '-- tables', (select s from s_tab), '-- functions', (select s from s_fun), '-- defaults', (select s from s_def),
    '-- not null', (select s from s_nn), '-- constraints', (select s from s_con), '-- indexes', (select s from s_idx),
    '-- views', (select s from s_view), '-- triggers', (select s from s_trg), '-- row level security', (select s from s_rls),
    '-- policies', (select s from s_pol), '-- table grants', (select s from s_tgrant), '-- function grants', (select s from s_fgrant),
    '-- buckets', (select s from s_bkt), '-- realtime', (select s from s_pub)) as out;
